source(file.path("helpers", "native-guard.R"))
# Public variation-level/role tests. Pure R only; no compiler or sampling.
source_mode<-nzchar(Sys.getenv("MEASUREMENTPKG_SOURCE"))
if(source_mode)for(f in list.files(file.path(Sys.getenv("MEASUREMENTPKG_SOURCE"),"R"),full.names=TRUE))source(f)else library(bmeas)
private<-function(n)if(source_mode)get(n,.GlobalEnv)else getFromNamespace(n,"bmeas")
passed<-0L
ok<-function(x,label){if(!isTRUE(x))stop(label);passed<<-passed+1L;cat("PASS",label,"\n")}
err<-function(expr,code,label=code){e<-tryCatch(force(expr),error=identity);ok(inherits(e,"measurement_error")&&identical(e$code,code),label)}
tasks<-c("x1","x2","x3")
d<-expand.grid(person=1:4,task=tasks,repeat_id=1:2,stringsAsFactors=FALSE)
d$y<-sin(seq_len(nrow(d))*.41)+seq_len(nrow(d))/31;d$obs<-paste0("o",seq_len(nrow(d)))
block<-function(parameters=NULL,data=d)observe(gaussian_model(),data,"person","task","y",units="points",observation_id="obs",parameters=parameters)
prepare<-function(b,m=bhmf(),prior=NULL,missing="error")bhmm(m,data=list(score=b),prior=prior,missing=missing,fit=FALSE)
ordinary<-prepare(block(),bhmf(G=~score$mu[tasks]))
ok(nrow(model_table(ordinary,"targets"))==3L&&nrow(model_table(ordinary,"free_loadings"))==3L,"unchanged Gaussian default roles and counts")
ok(all(check_model(ordinary)$identification$probe_ranks==6L),"unchanged default Gaussian covariance rank")
task<-prepare(block(list(mu="task",sigma=list(fixed=1))))
ok(nrow(model_table(task,"individual_targets"))==0L&&nrow(model_table(task,"targets"))==3L,"task means remain free without individual coordinates")
ok(all(get_prior(task)$class=="Intercept")&&sum(get_prior(task)$parameter_count)==3L,"one prior per task mean; fixed sigma absent")
ok(check_model(task)$identification$free_covariance_parameters==0L&&all(check_model(task)$identification$probe_ranks==0L),"zero covariance unknowns do not erase free means")
ok(all(model_table(task,"observation_operands")$operand%in%c("task_predictor","fixed_received")),"task and fixed operands explicit")
fixed<-prepare(block(list(mu=list(fixed=.2),sigma=list(fixed=1))))
ok(nrow(get_prior(fixed))==0L&&nrow(model_table(fixed,"targets"))==0L,"fully fixed block has no prior or fake eta coordinate")
ok(nrow(model_table(fixed,"response_domains"))==3L&&nrow(fixed$data_map$blocks$score)==nrow(d),"fixed means retain response domains and likelihood rows")
err(bhmm(fixed),"E_NO_FREE_PARAMETERS")
err(prepare(block(),bhmf()),"E_PARAMETER_COVERAGE","empty structure does not remove subject-task defaults")
err(prepare(block(list(mu="task")),bhmf(G=~score$mu[tasks])),"E_PARAMETER_LEVEL_CONFLICT")
err(prepare(block(list(mu=list(fixed=0))),bhmf(residual=list(targets=~score$mu[tasks]))),"E_PARAMETER_LEVEL_CONFLICT")
err(prepare(block(list(sigma="subject_task")),bhmf(G=~score$mu[tasks])),"E_PARAMETER_LEVEL_UNSUPPORTED")
legacy_data<-expand.grid(person=1:4,item=c("v1","v2","v3","s1","s2","s3"),stringsAsFactors=FALSE)
legacy_data$value_z<-sin(seq_len(nrow(legacy_data))*.31)
legacy<-demo_measurement_spec(legacy_data)
legacy$models$scores<-observe(gaussian_model(),legacy_data,"person","item","value_z",units="externally_standardized",source_id="synthetic_fixture_v1",parameters=list(sigma=list(fixed=1)))
err(check_measurement(legacy),"E_PARAMETER_LEVEL_UNSUPPORTED","legacy revalidation refuses injected level-aware blocks")
err(stan_data(legacy),"E_PARAMETER_LEVEL_UNSUPPORTED","legacy data generation cannot ignore a fixed-noise override")
err(make_stan_code(legacy),"E_PARAMETER_LEVEL_UNSUPPORTED","legacy code generation cannot ignore a fixed-noise override")
err(block(list(unknown="task")),"E_PARAMETER_LEVEL")
err(block(structure(list("task","task"),names=c("mu","mu"))),"E_PARAMETER_LEVEL")
err(block(list(mu="fixed")),"E_PARAMETER_LEVEL")
err(block(list(mu=list(fixed=1,extra=TRUE))),"E_PARAMETER_LEVEL")
err(block(list(mu=list(fixed=c(1,2)))),"E_PARAMETER_FIXED")
err(block(list(mu=list(fixed=Inf))),"E_PARAMETER_FIXED")
err(block(list(mu=NULL)),"E_PARAMETER_LEVEL")
err(block(list(mu=list(fixed=1,scale="log"))),"E_PARAMETER_SCALE")
ok(identical(block(list(mu=list(fixed=1,scale=NULL)))$parameter_levels,block(list(mu=list(fixed=1)))$parameter_levels),"nested scale NULL captures the explicit natural default")
err(block(list(mu=list(fixed=NULL))),"E_PARAMETER_FIXED")
err(prepare(block(list(mu=list(fixed=c(x1=1,x2=2))))),"E_PARAMETER_FIXED_TASKS")
err(prepare(block(list(mu=list(fixed=c(x1=1,x2=2,x4=3))))),"E_PARAMETER_FIXED_TASKS")
err(prepare(block(list(sigma=list(fixed=0))),bhmf(G=~score$mu[tasks])),"E_PARAMETER_FIXED_SUPPORT")
err(prepare(block(list(sigma=list(fixed=-1000,scale="predictor"))),bhmf(G=~score$mu[tasks])),"E_PARAMETER_NUMERICAL")
err(prepare(block(list(sigma=list(fixed=1000,scale="predictor"))),bhmf(G=~score$mu[tasks])),"E_PARAMETER_NUMERICAL")
values<-c(x3=.3,x1=.1,x2=.2);choice<-list(mu=list(fixed=values),sigma=list(fixed=1))
captured<-block(choice);values[]<-9;choice$mu$fixed[]<-8
captured_spec<-prepare(captured)
ok(identical(model_table(captured_spec,"fixed_parameters")$fixed_received[1:3],c(.1,.2,.3)),"named fixed task values captured and aligned exactly")
bad<-captured;bad$parameter_levels$choices$mu$value[1]<-4
err(prepare(bad),"E_SPEC_CHANGED")
permuted<-prepare(block(list(mu=list(fixed=c(x2=.2,x3=.3,x1=.1)),sigma=list(fixed=1)),d[nrow(d):1,]))
fields<-c("key","role","level","fixed_received","fixed_predictor")
ok(identical(model_table(captured_spec,"parameter_roles")[fields],model_table(permuted,"parameter_roles")[fields]),"row and fixed-map order do not change scientific role map")
copy<-unserialize(serialize(captured_spec,NULL));ok(identical(model_table(copy),model_table(captured_spec)),"captured fixed context survives serialization")
err(prepare(captured,prior=set_prior("normal(0,1)","Intercept",target=~score$mu["x1"])),"E_PRIOR_SELECTOR")
err(prepare(block(list(mu="task",sigma=list(fixed=1))),prior=set_prior("half_normal(1)","sigma",target=~score$sigma[tasks])),"E_PRIOR_SELECTOR")
task_prior<-prepare(block(list(mu="task",sigma=list(fixed=1))),prior=set_prior("normal(-.3,.7)","Intercept",target=~score$mu[tasks]))
ok(all(get_prior(task_prior)$prior=="normal(-.3,.7)"),"grouped task intercept priors retain predictor role")
ok(identical(block(list(mu="task"))$model,gaussian_model()),"level override does not mutate observation model metadata")

# Fixed sigma changes actual covariance/propriety premises, not data or priors.
one<-d[d$repeat_id==1L,,drop=FALSE]
residual<-bhmf(residual=list(targets=~score$mu[tasks]))
known_noise<-prepare(block(list(sigma=list(fixed=1)),one),residual)
ok(all(check_model(known_noise)$identification$probe_ranks==3L)&&check_model(known_noise)$identification$status=="local_rank_full_not_global_proof","fixed sigma identifies independent stable residuals without repeats")
unknown_noise<-prepare(block(NULL,one),residual)
ok(check_model(unknown_noise)$identification$status=="proven_unidentified","free sigma counterpart remains confounded")
owner<-list(type="variance_share",targets=~score$mu[c("x1","x2")],components=~G,residual=TRUE,shares=~1)
hybrid<-bhmf(G=~score$mu[tasks],decomposition=list(a=owner))
# Levels are parameter-wide; use three Gaussian blocks to fix one task's sigma.
wide<-data.frame(person=1:4,x1=c(.1,.3,.6,.8),x2=c(.4,-.2,.8,.1),x3=c(-.3,.7,.2,.5))
blocks<-function(fixed_name)lapply(stats::setNames(tasks,tasks),function(name)observe(gaussian_model(),data.frame(person=wide$person,task="t",y=wide[[name]]),"person","task","y",units="points",parameters=if(name==fixed_name)list(sigma=list(fixed=.8))else NULL))
hm<-bhmf(G=~x1$mu["t"]+x2$mu["t"]+x3$mu["t"],decomposition=list(a=list(type="variance_share",targets=~x1$mu["t"]+x2$mu["t"],components=~G,residual=TRUE,shares=~1)))
hs<-bhmm(hm,data=blocks("x1"),subjects="shared",fit=FALSE)
ok(all(check_model(hs)$identification$probe_ranks==6L)&&check_model(hs)$identification$status=="local_rank_full_not_global_proof","fixed noise at actual owner target pins share confounding direction")
he<-bhmm(hm,data=blocks("x3"),subjects="shared",fit=FALSE)
ok(check_model(he)$identification$status=="proven_unidentified"&&all(check_model(he)$identification$probe_ranks==5L),"unrelated fixed noise does not pin owner share direction")
single<-data.frame(person="p",task="t",y=.4,obs="single")
matching<-prepare(block(list(mu=list(fixed=.4)),single))
ok(check_model(matching)$posterior_propriety$status=="proven_improper","one exact response at fixed mean can collapse free Gaussian sigma")
mismatch<-prepare(block(list(mu=list(fixed=.2)),single))
ok(check_model(mismatch)$posterior_propriety$status=="no_scoped_collapse_detected","mismatching fixed mean does not meet collapse proof")
free_mean_one<-prepare(block(list(mu="task"),single))
ok(check_model(free_mean_one)$posterior_propriety$status=="no_scoped_collapse_detected","one response with free task mean is below scoped collapse threshold")
two<-rbind(single,transform(single,person="p2",obs="two"))
free_mean_two<-prepare(block(list(mu="task"),two))
ok(check_model(free_mean_two)$posterior_propriety$status=="proven_improper","two exact responses with free task mean meet scoped threshold")
fixed_noise_repeat<-prepare(block(list(mu="task",sigma=list(fixed=.5)),two))
ok(check_model(fixed_noise_repeat)$posterior_propriety$status=="no_scoped_collapse_detected","fixed positive sigma blocks collapse proof")
missing_data<-d;missing_data$y[missing_data$task=="x3"]<-NA_real_
missing_spec<-prepare(block(list(mu="task"),missing_data),missing="observed_only")
checks<-check_model(missing_spec)
ok(nrow(model_table(missing_spec,"targets"))==3L,"task domain retained through whole-task response exclusion")
ok(checks$identification$status=="proven_unidentified"&&all(c("score::mu::x3","score::sigma::x3")%in%checks$identification$uninformed_parameters),"uninformed task mean and free noise are explicit")
ok(!any(checks$identification$moments$row==3L),"all-missing task contributes no artificial covariance moment")
missing_prior<-get_prior(missing_spec)
ok(all(missing_prior$status[missing_prior$target%in%c("score::mu::x3","score::sigma::x3")]=="missing")&&all(missing_prior$calibration_status[missing_prior$target%in%c("score::mu::x3","score::sigma::x3")]=="not_available_no_observed_responses"),"missing-task calibration is unavailable, never invented")
empty<-single;empty$y<-NA_real_
empty_free<-bhmm(bhmf(),data=list(seen=block(list(mu="task"),single),empty=block(list(mu="task"),empty)),subjects="shared",missing="observed_only",fit=FALSE)
ok(nrow(empty_free$data_map$blocks$empty)==0L&&nrow(model_table(empty_free,"parameter_roles"))==4L,"wholly excluded block retains parameter domains without fabricated likelihood rows")
ok(all(c("empty::mu::t","empty::sigma::t")%in%check_model(empty_free)$identification$uninformed_parameters),"empty block free means and noise remain visibly uninformed")
empty_fixed<-bhmm(bhmf(),data=list(seen=block(list(mu="task",sigma=list(fixed=1)),single),empty=block(list(mu=list(fixed=.2),sigma=list(fixed=.8)),empty)),subjects="shared",missing="observed_only",fit=FALSE)
ok(check_model(empty_fixed)$identification$status=="local_rank_full_not_global_proof"&&nrow(get_prior(empty_fixed))==1L,"empty fixed-only block adds no phantom unknown or missing prior")
ok(nrow(check_model(empty_fixed)$identification$moments)==0L,"empty fixed-only domain and observed mean-only known-noise domain supply no varying covariance moment")
err(prepare(block(list(mu="task"),empty),missing="observed_only"),"E_EMPTY_DATA")

# A custom task predictor retains its scientific role even when positive.
custom<-function(support="real",predictor="identity",receives="eta",level="task") {
  p<-parameter_spec(support,predictor,receives,level,"custom_units","arbitrary named predictor",role="predictor")
  model<-new_observation_model("custom_location","1",response_schema(y="real"),list(offset=p,noise=parameter_spec("positive","log","theta","task","custom_units","observation noise")),
    stan_density(symbol="normal_lpdf",arguments=c("y","offset","noise"),argument_types=rep("real",3),normalized=TRUE,approximation="exact",builtin=TRUE),model_capabilities(fit=TRUE))
  register_stan_adapter(model)
}
cb<-observe(custom("positive","log"),single,"person","task","y",units="custom_units")
cs<-bhmm(bhmf(),data=list(custom=cb),fit=FALSE)
ok(identical(model_table(cs,"targets")$parameter,"offset")&&identical(model_table(cs,"observation_parameters")$parameter,"noise"),"positive task predictor is not reclassified as observation noise")
ok(get_prior(cs)$class[grepl("offset",get_prior(cs)$parameter)]=="Intercept","custom task predictor uses predictor intercept prior")
err(parameter_spec("real","identity","eta",c("subject_task","task"),"x","x",role="predictor"),"E_PARAMETER_LEVEL")
ambiguous<-custom();ambiguous$parameters$offset$levels<-c("subject_task","task")
err(register_stan_adapter(ambiguous),"E_ADAPTER")
err(bhmm(bhmf(),data=list(custom=observe(ambiguous,single,"person","task","y",units="custom_units",parameters=list(offset="task"))),fit=FALSE),"E_ADAPTER")
fixed_custom<-custom("unit_interval","logit","theta","fixed")
for(endpoint in c(0,1)) {
  b<-observe(fixed_custom,single,"person","task","y",units="custom_units",parameters=list(offset=list(fixed=endpoint)))
  s<-bhmm(bhmf(),data=list(custom=b),fit=FALSE);r<-model_table(s,"fixed_parameters")
  ok(r$fixed_received==endpoint&&is.na(r$fixed_predictor)&&r$predictor_representation=="no_finite_predictor","theta endpoint constant has no fake finite eta")
}
err(bhmm(bhmf(),data=list(custom=observe(fixed_custom,single,"person","task","y",units="custom_units")),fit=FALSE),"E_PARAMETER_FIXED")
err(bhmm(bhmf(),data=list(custom=observe(fixed_custom,single,"person","task","y",units="custom_units",parameters=list(offset=list(fixed=100,scale="predictor")))),fit=FALSE),"E_PARAMETER_NUMERICAL")

# Pinned M3 scale and role fidelity, when the separately licensed resource exists.
resource<-Sys.getenv("MEASUREMENTPKG_M3_RESOURCE")
if(nzchar(resource)&&file.exists(resource)) {
  md<-expand.grid(person=1:4,task=c("t1","t2"),stringsAsFactors=FALSE);md$obs<-paste0("m",seq_len(nrow(md)))
  md$counts<-I(matrix(0L,nrow(md),10L));md$counts[,1]<-2L;md$options<-I(matrix(1L,nrow(md),10L))
  model<-m3_cs_model(resource)
  bind<-function(parameters)observe(model,md,"person","task",fields=list(counts="counts",options="options"),units="count",observation_id="obs",parameters=parameters)
  mt<-c("t1","t2");mf<-bhmf(residual=list(targets=~cs$a[mt]))
  ps<-c(set_prior("normal(0,1)","Intercept"),set_prior("half_normal(1)","parameter_sd"))
  b<-bind(list(c="task",ra=list(fixed=100,scale="predictor"),rc=list(fixed=.3,scale="natural")))
  s<-bhmm(mf,data=list(cs=b),prior=ps,fit=FALSE);roles<-model_table(s,"parameter_roles")
  ok(identical(b$model,model),"pinned original parameter/adapter/resource contract unchanged")
  ok(sum(get_prior(s)$class=="Intercept")==4L&&sum(get_prior(s)$class=="parameter_sd")==2L&&nrow(model_table(s,"observation_parameters"))==0L,"M3 a-person/c-task allocates exact roles without invented noise")
  ok(all(roles$fixed_received[roles$parameter=="ra"]==100),"finite predictor100 never logit-roundtrips")
  ok(all(roles$fixed_received[roles$parameter=="rc"]==qlogis(.3)),"M3 natural probability receives one inverse-logit-link conversion")
  op<-model_table(s,"observation_operands")
  ok(all(op$operand[op$argument=="c"]=="task_predictor")&&all(op$operand[op$argument%in%c("ra","rc")]=="fixed_received"),"M3 multi-argument operands preserve each level")
  ok(check_model(s)$identification$status=="not_assessed","cognitive information does not inherit Gaussian identification proof")
  for(scale in c("natural","predictor","received")) {
    value<-if(scale=="natural").5 else log(.5)
    b<-bind(list(a=list(fixed=value,scale=scale),c="task",ra=list(fixed=0,scale="predictor"),rc=list(fixed=0,scale="received")))
    t<-bhmm(bhmf(),data=list(cs=b),prior=set_prior("normal(0,1)","Intercept"),fit=FALSE)
    ok(all(model_table(t,"fixed_parameters")$fixed_received[model_table(t,"fixed_parameters")$parameter=="a"]==log(.5)),paste("equivalent M3 activation constant",scale))
  }
  err(bhmm(mf,data=list(cs=bind(list(c="task",ra=list(fixed=1),rc=list(fixed=.3)))),prior=ps,fit=FALSE),"E_PARAMETER_RECEIVER_UNQUALIFIED")
  huge<-bhmm(bhmf(),data=list(cs=bind(list(a=list(fixed=1000,scale="predictor"),c="task",ra=list(fixed=0,scale="predictor"),rc=list(fixed=0,scale="predictor")))),prior=set_prior("normal(0,1)","Intercept"),fit=FALSE)
  ok(all(model_table(huge,"fixed_parameters")$fixed_received[model_table(huge,"fixed_parameters")$parameter=="a"]==1000),"finite received eta is bindable even when optional natural display overflows; kernel safety remains unassessed")
  fd<-expand.grid(person=1:2,route=1:3,content=1:3,stringsAsFactors=FALSE)
  fd$task<-paste0("display_",fd$route,"_",fd$content);fd$obs<-paste0("f",seq_len(nrow(fd)))
  fd$counts<-I(matrix(0L,nrow(fd),10L));fd$options<-I(matrix(0L,nrow(fd),10L))
  active<-list(c(1:4,10),c(5:7,9:10),5:10)
  for(i in seq_len(nrow(fd))){cols<-active[[fd$route[i]]];fd$options[i,cols]<-1L;fd$counts[i,cols[1L]]<-2L}
  fm<-m3_model(resource);domains<-m3_reference_domain()
  fb<-observe(fm,fd,"person","task",fields=list(counts="counts",options="options",route="route",content="content"),
    units="count",observation_id="obs",parameter_bindings=m3_reference_bindings(fd,"obs"),
    parameters=list(c="task",ra=list(fixed=.4),rc=list(fixed=.6)))
  atasks<-domains$task[domains$parameter=="a"]
  fs<-bhmm(bhmf(residual=list(targets=~full$a[atasks])),data=list(full=fb),prior=ps,fit=FALSE)
  fop<-model_table(fs,"observation_operands")
  ok(nrow(model_table(fs,"targets"))==18L&&nrow(model_table(fs,"individual_targets"))==9L,"routed aliases resolve original a/c domains, not observation task labels")
  ok(sum(get_prior(fs)$class=="Intercept")==18L&&sum(get_prior(fs)$class=="parameter_sd")==9L,"routed task c aliases share one intercept per logical key")
  ok(all(fop$received_constant[fop$argument=="ra_fixed"]==100)&&all(fop$value_source[fop$argument=="ra_fixed"]=="intrinsic_route_literal"),"MU intrinsic ra100 remains literal despite block ra override")
  ok(all(fop$received_constant[fop$argument=="ra"]==qlogis(.4)),"CS ra target override applies only to scientific target arguments")
  old<-fop[fop$route%in%c("MU_no","MU_yes")&fop$argument=="c1",]
  ok(all(vapply(split(old$eta_index,old$target),function(x)length(unique(x))==1L,logical(1))),"shared MU old-c target maps to the same task eta across both routes")
  ok(identical(fb$model,fm)&&identical(fb$parameter_bindings,m3_reference_bindings(fd,"obs")),"pinned routed model and literal bindings unchanged")
  missing_fd<-fd;missing_fd$counts[missing_fd$route==3L,]<-NA_integer_
  missing_fb<-observe(fm,missing_fd,"person","task",fields=list(counts="counts",options="options",route="route",content="content"),
    units="count",observation_id="obs",parameter_bindings=m3_reference_bindings(missing_fd,"obs"),
    parameters=list(c="task",ra=list(fixed=.4),rc=list(fixed=.6)))
  missing_fs<-bhmm(bhmf(residual=list(targets=~full$a[atasks])),data=list(full=missing_fb),prior=ps,missing="observed_only",fit=FALSE)
  ok(all(paste0("full::c::MU_new_",c("color","image","position"))%in%check_model(missing_fs)$identification$uninformed_parameters),"excluded route leaves task-c unknowns visibly uninformed without rewriting its domain")
  ok(!any(parameter_binding_table(missing_fs)$route=="MU_yes"),"public route binding inspection preserves retained-domain missingness semantics")
  ok(grepl("original route",attr(parameter_binding_table(fs),"scope"),fixed=TRUE),"route binding table distinguishes original aliases from effective level operands")
  empty_fd<-fd;empty_fd$counts[,]<-NA_integer_
  empty_fb<-observe(fm,empty_fd,"person","task",fields=list(counts="counts",options="options",route="route",content="content"),
    units="count",observation_id="obs",parameter_bindings=m3_reference_bindings(empty_fd,"obs"),
    parameters=list(a=list(fixed=.5),c=list(fixed=.5),ra=list(fixed=.4),rc=list(fixed=.6)))
  empty_full<-bhmm(bhmf(),data=list(seen=block(list(mu="task",sigma=list(fixed=1)),single),full=empty_fb),subjects="shared",missing="observed_only",fit=FALSE)
  empty_table<-parameter_binding_table(empty_full)
  ok(nrow(empty_table)==0L&&identical(names(empty_table),names(parameter_binding_table(fs))),"wholly excluded routed block returns the same typed zero-row binding schema")
  ok(is.double(empty_table$fixed_value)&&is.integer(empty_table$row_index)&&is.character(empty_table$target_key),"empty routed bindings preserve column storage types")
}
sdm_resource<-Sys.getenv("MEASUREMENTPKG_SDM_RESOURCE")
if(nzchar(sdm_resource)&&file.exists(sdm_resource)) {
  sd<-data.frame(person=1:4,task="angle",error=c(-.2,.1,.3,-.1),run=1:4)
  sm<-sdm_reference_model(sdm_resource)
  sb<-observe(sm,sd,"person","task",fields=list(error="error",run="run"),units="radian",
    parameters=list(log_c=list(fixed=-.2,scale="natural"),log_kappa="task"))
  ss<-bhmm(bhmf(),data=list(angle=sb),prior=set_prior("normal(.4,.3)","Intercept"),fit=FALSE)
  ok(identical(model_table(ss,"targets")$parameter,"log_kappa")&&nrow(get_prior(ss))==1L,"SDM task log-kappa remains one original predictor intercept")
  ok(identical(model_table(ss,"fixed_parameters")$fixed_received,-.2),"SDM logical log_c uses its declared identity link, with no name-based extra exp")
  ok(identical(sb$model,sm),"SDM original wrapper and quadrature constants unchanged")
}
cat(passed,"parameter-level R/IR checks passed\n")
